mapper.select:
SELECT id,business_type,business_sn,item_key
FROM reminder_todo
WHERE node_code=#{nodeCode} AND round_key=#{roundKey}

mapper.update:
UPDATE reminder_todo SET status=2
WHERE node_code='GOODS_READY' AND assignee_userid=#{userid} AND status=0
  AND id IN #{id}

UPDATE reminder_todo SET status=2
WHERE node_code='RF_CREATE' AND status=0
  AND business_sn IN #{sn}

UPDATE reminder_todo SET status=1
WHERE node_code=#{nodeCode} AND assignee_userid=#{userid} AND status=0
  AND id IN #{id}

UPDATE reminder_todo SET status=1 WHERE node_code=#{nodeCode} AND status=0

    AND id NOT IN #{id}


    AND business_sn NOT IN
    #{sn}

UPDATE reminder_push_record
SET send_status=#{sendStatus},send_result=#{resultJson},next_retry_at=#{nextRetryAt}
WHERE id=#{batchId} AND record_type=1 AND send_status=1

UPDATE reminder_push_record
SET send_status=1,send_result=#{contextJson},sent_at=#{now},next_retry_at=NULL
WHERE id=#{id} AND record_type=1 AND send_status IN (0,3) AND next_retry_at<=#{now}

mapper.select:
SELECT todo_id,reason,created_at FROM reminder_reason_history
WHERE todo_id IN #{id}
ORDER BY created_at DESC,id DESC
